head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[input > P > checkMaxByteOnInput]<br/>maxByteLength 속성이 적용되었을때 입력값에 대한 Byte 수 체크가 처리되는 시점을 설정합니다.",
    "validation" : [
        "미설정 시 입력값으로 눌린 키가 떼어졌을때 Byte 수를 체크합니다.",        
        "미설정 시 maxByteLength 를 초과했을때 입력된 문자가 컴포넌트에 표시되었다가 제거됩니다.",        
        "true 설정 시 입력값이 변경된 시점에 Byte 수를 체크합니다.",      
        "true 설정 시 maxByteLength 를 초과했을때 입력값이 컴포넌트에 표시되지 않습니다.",      
        "false 설정 시 입력값으로 눌린 키가 떼어졌을때 Byte 수를 체크합니다.",   
        "false 설정 시 maxByteLength 를 초과했을때 입력된 문자가 컴포넌트에 표시되었다가 제거됩니다.",           
        "우선 순위에 의해 maxlength 속성이 적용된 경우는 동작하지 않습니다.",
        "붙여넣기로 입력값을 설정하는 경우도 적용됩니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.get_text = function(target) {    
    let rtn = '';
    let tagName = target.tagName

    if (tagName !== "INPUT") {
        rtn = target.textContent
        wf_body_bottom.getObj("scwin").setReturnValue("text : " + rtn);    
    }
    else {
        rtn = target.value
        wf_body_bottom.getObj("scwin").setReturnValue("text : " + rtn);   
    }    
}



scwin.target_onkeyup = function (e) {
    scwin.get_text(e.target);
};
